在多线程环境下使用以下线程安全缓存队列时，在高并发消费时偶发 `IndexError: pop from empty deque`：
```python
from collections import deque
import threading

class SafeQueue:
    def __init__(self):
        self.q = deque()
        self.lock = threading.Lock()

    def put(self, item):
        with self.lock:
            self.q.append(item)

    def get(self):
        if len(self.q) > 0:
            # Bug发生点：检查与pop之间未加锁保护/条件检查脱节
            with self.lock:
                return self.q.popleft()
        return None
```
