    def c3(): log.append('c3')
    so.add_step(a1, c1)
    so.add_step(a2, c2)
    so.add_step(a3_fail, c3)
    res = so.execute()
    assert res.get('success') is False
    assert log == ['a1', 'a2', 'a3', 'c2', 'c1'], f'Unexpected saga log: {log}'
    return True
result = test_saga()
